      "state": {
        "timeMarker": 7,
        "growthRate": 0.8,
        "viewMode": "Population f(t)"
      }
    },
    {
      "title": "The growth-rate curve",
      "narration": "Switching on f'(t) reveals a single hump whose peak sits directly under the inflection point. Growth rate rises, peaks at c/2, then decays — the S-curve is the accumulated story of that hump.",
      "state": {
        "timeMarker": 2.7,
        "growthRate": 0.8,
        "viewMode": "Population + growth rate f'(t)"
      }
    },
    {
