// @FIGURE_CODE_BEGIN
(function () {
  /* ── model constants ─────────────────────────────────────────── */
  var XMIN = -3.2, XMAX = 12.8, YMIN = -0.30, YMAX = 1.32;
  var C = 1, A = 9;
  var AXIS_Y = -0.05;                     // visual baseline (t-axis drawn slightly below f=0)
  var NAVY = '#16537e', ORANGE = '#e0703c', TEAL = '#2a9d8f',
      MARK = '#c0392b', GRAY = '#b7bec6', INK = '#111111';

  var bVal = 0.8, tVal = 0, derivOn = false, markerOn = false;

  function fpop(t, b) { return C / (1 + A * Math.exp(-b * t)); }
  function fprime(t, b) { var v = fpop(t, b); return b * v * (1 - v / C); }
  function dScale(b) { return Math.min(2.75, 0.78 * C / (b * C / 4)); }

  /* ── canvas ──────────────────────────────────────────────────── */
  var container = document.getElementById('container');
  var canvas = document.createElement('canvas');
  canvas.style.cssText = 'width:100%;height:100%;display:block';
  container.appendChild(canvas);

  var hits = [];

  /* ── small drawing helpers ───────────────────────────────────── */
  function setFont(ctx, fs, style) {
    ctx.font = (style ? style + ' ' : '') + fs.toFixed(1) + 'px Georgia, "Times New Roman", serif';
  }
  function halo(ctx, str, x, y, hw) {
    ctx.save();
    ctx.lineWidth = hw || 3.2; ctx.strokeStyle = '#ffffff'; ctx.lineJoin = 'round';
    ctx.strokeText(str, x, y);
    ctx.restore();
    ctx.fillText(str, x, y);
  }
  function arrowHead(ctx, x, y, ang, size, color) {
    ctx.save(); ctx.translate(x, y); ctx.rotate(ang);
    ctx.beginPath(); ctx.moveTo(0, 0);
    ctx.lineTo(-size, size * 0.42); ctx.lineTo(-size, -size * 0.42); ctx.closePath();
    ctx.fillStyle = color; ctx.fill(); ctx.restore();
  }
  function leader(ctx, x1, y1, x2, y2, color, lw, head) {
