  }
  function fracW(ctx, num, den, fs) {
    setFont(ctx, fs);
    return Math.max(ctx.measureText(num).width, ctx.measureText(den).width) + 5;
  }
  function drawFrac(ctx, num, den, xLeft, yMid, fs, color) {
    var w = fracW(ctx, num, den, fs), cx = xLeft + w / 2;
    setFont(ctx, fs);
    ctx.fillStyle = color; ctx.textAlign = 'center'; ctx.textBaseline = 'alphabetic';
    halo(ctx, num, cx, yMid - fs * 0.26);
    halo(ctx, den, cx, yMid + fs * 0.98);
    ctx.save();
    ctx.strokeStyle = '#fff'; ctx.lineWidth = Math.max(2, fs * 0.22);
    ctx.beginPath(); ctx.moveTo(xLeft + 1, yMid); ctx.lineTo(xLeft + w - 1, yMid); ctx.stroke();
    ctx.strokeStyle = color; ctx.lineWidth = Math.max(1, fs * 0.075);
    ctx.beginPath(); ctx.moveTo(xLeft + 1, yMid); ctx.lineTo(xLeft + w - 1, yMid); ctx.stroke();
    ctx.restore();
    return w;
  }
  function interceptLabelW(ctx, fs) {
    setFont(ctx, fs);
    return ctx.measureText('(0, ').width + fracW(ctx, 'c', '1 + a', fs) + ctx.measureText(')').width;
  }
  function drawInterceptLabel(ctx, xLeft, yMid, fs) {
    setFont(ctx, fs);
    var x = xLeft;
    ctx.fillStyle = INK; ctx.textAlign = 'left'; ctx.textBaseline = 'middle';
    halo(ctx, '(0, ', x, yMid); x += ctx.measureText('(0, ').width;
    x += drawFrac(ctx, 'c', '1 + a', x, yMid, fs, INK);
    setFont(ctx, fs); ctx.fillStyle = INK; ctx.textAlign = 'left'; ctx.textBaseline = 'middle';
    halo(ctx, ')', x, yMid);
  }
  function inflLabelW(ctx, fs) {
    setFont(ctx, fs);
    return ctx.measureText('(').width + fracW(ctx, 'ln(a)', 'b', fs) +
      ctx.measureText(', ').width + fracW(ctx, 'c', '2', fs) + ctx.measureText(')').width;
  }
  function drawInflLabel(ctx, xLeft, yMid, fs) {
    setFont(ctx, fs);
    var x = xLeft;
    ctx.fillStyle = INK; ctx.textAlign = 'left'; ctx.textBaseline = 'middle';
    halo(ctx, '(', x, yMid); x += ctx.measureText('(').width;
    x += drawFrac(ctx, 'ln(a)', 'b', x, yMid, fs, INK);
    setFont(ctx, fs); ctx.fillStyle = INK; ctx.textAlign = 'left'; ctx.textBaseline = 'middle';
    halo(ctx, ', ', x, yMid); x += ctx.measureText(', ').width;
    x += drawFrac(ctx, 'c', '2', x, yMid, fs, INK);
