    var bx = xLeft + wl;
    ctx.textAlign = 'center'; ctx.textBaseline = 'alphabetic';
    halo(ctx, 'c', bx + fw / 2, yMid - fs * 0.26);
    ctx.save();
    ctx.strokeStyle = '#fff'; ctx.lineWidth = Math.max(2, fs * 0.22);
    ctx.beginPath(); ctx.moveTo(bx + 1, yMid); ctx.lineTo(bx + fw - 1, yMid); ctx.stroke();
    ctx.strokeStyle = color; ctx.lineWidth = Math.max(1, fs * 0.075);
    ctx.beginPath(); ctx.moveTo(bx + 1, yMid); ctx.lineTo(bx + fw - 1, yMid); ctx.stroke();
    ctx.restore();
    var dx = bx + (fw - denW) / 2;
    ctx.textAlign = 'left'; ctx.textBaseline = 'alphabetic'; ctx.fillStyle = color;
