  /* ── plugin: axes + guides (below curves) ────────────────────── */
  var underPlugin = {
    id: 'underLayer',
    beforeDatasetsDraw: function (chart) {
      var ctx = chart.ctx, area = chart.chartArea;
      if (!area) return;
      var X = function (v) { return chart.scales.x.getPixelForValue(v); };
      var Y = function (v) { return chart.scales.y.getPixelForValue(v); };
      var pw = area.right - area.left, ph = area.bottom - area.top;
      var s = Math.max(0.55, Math.min(1.6, Math.min(pw, ph) / 430));
      var yA = Y(AXIS_Y), x0 = X(0);
      var t0 = Math.log(A) / bVal;

