        ctx.save();
        ctx.strokeStyle = GRAY; ctx.lineWidth = 1 * s; ctx.setLineDash([4 * s, 4 * s]);
        ctx.beginPath(); ctx.moveTo(area.left, Y(C / 2)); ctx.lineTo(area.right, Y(C / 2)); ctx.stroke();
        ctx.restore();
