      /* axes */
      ctx.save();
      ctx.strokeStyle = INK; ctx.lineWidth = Math.max(1, 1.5 * s); ctx.setLineDash([]);
      ctx.beginPath();
      ctx.moveTo(area.left + 9 * s, yA); ctx.lineTo(area.right - 16 * s, yA);
      ctx.moveTo(x0, area.bottom - 4 * s); ctx.lineTo(x0, area.top + 17 * s);
      ctx.stroke();
      ctx.restore();
      var hs = 7 * s;
