      arrowHead(ctx, area.left + 8 * s, yA, Math.PI, hs, INK);
      arrowHead(ctx, x0, area.top + 15 * s, -Math.PI / 2, hs, INK);
      arrowHead(ctx, x0, area.bottom - 2 * s, Math.PI / 2, hs, INK);

