    var h = hitTest(px, py);
    if (h) { canvas.style.cursor = 'pointer'; showTooltip(h.tip, e); }
    else if (nearCurve(px, py)) { canvas.style.cursor = 'grab'; showTooltip('Drag along the curve to move the marker', e); }
    else { canvas.style.cursor = 'default'; hideTooltip(); }
  });
  canvas.addEventListener('mousedown', function (e) {
    var r = canvas.getBoundingClientRect(), px = e.clientX - r.left, py = e.clientY - r.top;
    if (!hitTest(px, py) && nearCurve(px, py)) { dragging = true; setT(xToT(px)); }
